insert into public.courses ("id", "title", "subject", "grade", "description", "color", "icon", "teacher_id", "exam_date") values
('math-12', 'Calculus: Change & Motion', 'Mathematics', 12, 'Derivatives, limits and integrals — learned through real motion, money and shapes you can drag.', '#FF9900', 'sigma', '00000000-0000-4000-8000-000000000001', '2026-11-20'),
('eng-12', 'English: Argument & Craft', 'English', 12, 'Rhetoric, voice and structure. Every essay is written inside BOLT so the thinking path counts, not just the final page.', '#5B7CFA', 'feather', '00000000-0000-4000-8000-000000000001', '2026-11-24'),
('phy-12', 'Physics: Mechanics of the Real World', 'Physics', 12, 'Motion, forces, gravity, energy and collisions — every lesson has a simulation you can break and fix.', '#2FA36B', 'atom', '00000000-0000-4000-8000-000000000001', '2026-11-18')
insert into public.lessons ("id", "course_id", "position", "title", "youtube_id", "duration_min", "summary", "topics", "skills", "interactive", "transcript") values
('math-12-l1', 'math-12', 1, 'The Essence of Calculus', 'WUvTyaaNkzM', 17, 'Why calculus exists: slicing a circle into rings reveals how area, slope and tiny changes are connected.', '[{"id":"area-rings","name":"Area by slicing into rings"},{"id":"tiny-changes","name":"Reasoning with dx"},{"id":"area-under-graph","name":"Area under a graph"}]'::jsonb, '["problem-solving","critical-thinking"]'::jsonb, 'circle-rings', '[{"t":0,"text":"The goal: make you feel like you could have invented calculus yourself."},{"t":60,"text":"Take a circle of radius 3. Split it into many thin concentric rings."},{"t":150,"text":"Each ring, straightened out, is almost a rectangle of width dr and length 2πr."},{"t":240,"text":"Adding up all 2πr·dr rectangles is the area under the graph of 2πr — a triangle."},{"t":360,"text":"As dr shrinks, the sum approaches exactly πr². That is the essence of an integral."},{"t":480,"text":"The same question for other graphs leads to the idea of an integral function A(x)."},{"t":600,"text":"A tiny change dA is approximately f(x)·dx, so dA/dx = f(x): the derivative."},{"t":780,"text":"Integrals and derivatives are inverses — the fundamental theorem of calculus."},{"t":900,"text":"Recap: tiny slices, approximate rectangles, sums becoming exact."}]'::jsonb),
('math-12-l2', 'math-12', 2, 'The Paradox of the Derivative', '9vKqVkMQHKk', 17, 'Instantaneous rate of change sounds impossible. A car’s distance graph shows what the derivative really measures.', '[{"id":"rate-of-change","name":"Average vs instantaneous rate"},{"id":"tangent-slope","name":"Slope of the tangent line"},{"id":"derivative-definition","name":"Definition of the derivative"}]'::jsonb, '["problem-solving","critical-thinking"]'::jsonb, 'tangent-explorer', '[{"t":0,"text":"A car travels 100 m in 10 s. Its distance-vs-time graph curves upward then flattens."},{"t":90,"text":"Velocity is distance change over a time interval: rise over run between two points."},{"t":200,"text":"Shrink the interval dt. The secant line approaches the tangent line."},{"t":320,"text":"The derivative ds/dt is the slope of that tangent — not a change over zero time."},{"t":440,"text":"Example: s(t) = t³. The derivative works out to 3t²."},{"t":560,"text":"At t = 0 the slope is 0. Is the car moving? The paradox of an instant."},{"t":700,"text":"Derivative = best constant approximation for rate of change around a point."},{"t":860,"text":"Next time: deriving formulas like the power rule from geometry."}]'::jsonb),
('math-12-l3', 'math-12', 3, 'Derivative Formulas Through Geometry', 'S0_qX4VJhMQ', 18, 'The power rule and the derivative of sine fall out of squares, cubes and the unit circle.', '[{"id":"power-rule","name":"Power rule"},{"id":"sine-derivative","name":"Derivative of sin and cos"},{"id":"geometric-reasoning","name":"Geometric reasoning with dx"}]'::jsonb, '["problem-solving","creative-thinking"]'::jsonb, 'power-rule-square', '[{"t":0,"text":"A square with side x has area x². Grow the side by dx."},{"t":110,"text":"The new area adds two thin strips (x·dx each) plus a negligible corner."},{"t":220,"text":"So d(x²) = 2x·dx — the derivative of x² is 2x."},{"t":340,"text":"For x³ picture a cube: three square faces give 3x²."},{"t":470,"text":"The general power rule: d/dx xⁿ = n·xⁿ⁻¹."},{"t":600,"text":"For sin(θ), walk around the unit circle. A tiny dθ changes the height by cos(θ)·dθ."},{"t":760,"text":"Hence the derivative of sin is cos, and the derivative of cos is −sin."},{"t":900,"text":"Memorising less, seeing more."}]'::jsonb),
('math-12-l4', 'math-12', 4, 'Chain Rule & Product Rule', 'YG15m2VwSjA', 16, 'How to differentiate functions that are added, multiplied, or nested inside each other.', '[{"id":"sum-rule","name":"Sum rule"},{"id":"product-rule","name":"Product rule"},{"id":"chain-rule","name":"Chain rule"}]'::jsonb, '["problem-solving"]'::jsonb, 'product-rule-box', '[{"t":0,"text":"Three ways to combine functions: add, multiply, compose."},{"t":100,"text":"Sum rule: the derivative of a sum is the sum of derivatives."},{"t":220,"text":"Product rule: picture a box with sides g(x) and h(x). Area changes by g·dh + h·dg."},{"t":400,"text":"Left d-right plus right d-left."},{"t":520,"text":"Chain rule: nested functions. A change dx causes dh, which causes dg."},{"t":660,"text":"d/dx g(h(x)) = g′(h(x))·h′(x). The inner derivative multiplies the outer."},{"t":820,"text":"Example: sin(x²) → cos(x²)·2x."}]'::jsonb),
('math-12-l5', 'math-12', 5, 'Limits & L’Hôpital’s Rule', 'kfF40MiS7zA', 18, 'What a limit really promises, and a trick for 0/0 situations that shows up in physics constantly.', '[{"id":"limit-intuition","name":"Limits as approach"},{"id":"epsilon-delta","name":"Epsilon–delta idea"},{"id":"lhopital","name":"L’Hôpital’s rule"}]'::jsonb, '["critical-thinking"]'::jsonb, 'limit-explorer', '[{"t":0,"text":"The derivative definition uses a limit as dx approaches 0 — never equals 0."},{"t":130,"text":"A limit exists when inputs close to a value give outputs close to a target."},{"t":280,"text":"Epsilon–delta: for any output tolerance ε there is an input tolerance δ."},{"t":450,"text":"sin(x)/x near 0 is 0/0 — undefined, but the graph clearly heads to 1."},{"t":600,"text":"L’Hôpital: for 0/0, compare the derivatives of top and bottom instead."},{"t":760,"text":"cos(0)/1 = 1. The rule works because near the point both functions are nearly linear."}]'::jsonb),
('math-12-l6', 'math-12', 6, 'Integration & the Fundamental Theorem', 'rfG8ce4nNh0', 21, 'From a velocity graph back to distance: area under a curve, antiderivatives and why the +C matters.', '[{"id":"riemann-sum","name":"Area as a sum of rectangles"},{"id":"antiderivative","name":"Antiderivatives"},{"id":"ftc","name":"Fundamental theorem"}]'::jsonb, '["problem-solving"]'::jsonb, 'riemann-area', '[{"t":0,"text":"You know the velocity of a car at every moment. How far did it travel?"},{"t":150,"text":"Velocity times a tiny time slice is a tiny distance — a thin rectangle."},{"t":300,"text":"Sum the rectangles: the area under the velocity graph equals the distance."},{"t":480,"text":"The antiderivative: a function whose derivative is v(t)."},{"t":660,"text":"Fundamental theorem: ∫ from a to b of v(t)dt = s(b) − s(a)."},{"t":900,"text":"Negative area means moving backwards."},{"t":1100,"text":"Any antiderivative works — the constant cancels."}]'::jsonb),
('math-12-l7', 'math-12', 7, 'Area, Slope & Averages', 'FnJqaIESC2s', 13, 'The average value of a function links area and slope — and explains why derivatives and integrals undo each other.', '[{"id":"average-value","name":"Average value of a function"},{"id":"area-slope-link","name":"Area ↔ slope connection"},{"id":"applied-integral","name":"Applied integrals"}]'::jsonb, '["critical-thinking","problem-solving"]'::jsonb, 'average-value', '[{"t":0,"text":"What is the average of sin(x) between 0 and π? Infinitely many values…"},{"t":120,"text":"Sample finitely many points, average them, then let the samples become infinite."},{"t":260,"text":"The average height = area ÷ width = (1/π)∫sin(x)dx."},{"t":420,"text":"Area is F(π) − F(0) where F is an antiderivative, so average = slope of F."},{"t":560,"text":"That is the deep reason area and slope are inverse ideas."},{"t":700,"text":"Application: average power, average speed, average price."}]'::jsonb),
('eng-12-l1', 'eng-12', 1, 'Writing Descriptively', 'RSoRzTtwgP4', 5, 'Pull a reader inside a scene with the senses, surprising connotations and “show, don’t tell”.', '[{"id":"sensory-detail","name":"Sensory detail"},{"id":"show-dont-tell","name":"Show, don’t tell"},{"id":"connotation","name":"Connotation & word choice"}]'::jsonb, '["creative-thinking","communication"]'::jsonb, 'essay-editor', '[{"t":0,"text":"Fiction is an illusion. Good writing pulls readers through the page into the story."},{"t":50,"text":"Choose words that engage sound, sight, taste, touch, smell and movement."},{"t":110,"text":"Avoid flat matter-of-fact statements: “it was cold” tells; frost in the air shows."},{"t":170,"text":"Create unexpected connections between story elements to spark imagination."},{"t":230,"text":"Help readers feel what characters feel, not only know what they feel."}]'::jsonb),
('eng-12-l2', 'eng-12', 2, 'Rhetoric: Ethos, Logos, Pathos', '3klMM9BkW5o', 5, 'Aristotle’s three appeals and how to build a persuasive essay — and how to notice when they are used on you.', '[{"id":"ethos","name":"Ethos (credibility)"},{"id":"logos","name":"Logos (reasoning)"},{"id":"pathos","name":"Pathos (emotion)"},{"id":"thesis","name":"Thesis statements"}]'::jsonb, '["critical-thinking","communication"]'::jsonb, 'essay-editor', '[{"t":0,"text":"Aristotle: rhetoric is the art of seeing the available means of persuasion."},{"t":40,"text":"Forensic rhetoric is about the past; epideictic about the present; deliberative about the future."},{"t":100,"text":"Ethos convinces the audience of your credibility or virtue."},{"t":140,"text":"Logos uses logic, examples, research and statistics."},{"t":180,"text":"Pathos appeals to emotion — the most common in media and advertising."},{"t":230,"text":"Knowing your audience, purpose, place and time decides which appeal to use."},{"t":260,"text":"Notice when these methods are being used on you."}]'::jsonb),
('eng-12-l3', 'eng-12', 3, 'Zombie Nouns & Clear Prose', 'dNlkHtMgcPQ', 5, 'Nominalizations drain life from sentences. Learn to put humans and active verbs back in.', '[{"id":"nominalization","name":"Spotting nominalizations"},{"id":"active-verbs","name":"Active verbs & agents"},{"id":"concision","name":"Concision"}]'::jsonb, '["communication"]'::jsonb, 'sentence-surgery', '[{"t":0,"text":"Add -ity, -tion or -ism to a word and you get a noun that sounds impressive but says less."},{"t":60,"text":"Nominalizations cannibalize active verbs and remove human beings from sentences."},{"t":130,"text":"“The proliferation of nominalizations…” — seven zombie nouns, no clear actor."},{"t":200,"text":"Rewrite: Writers who overload sentences with nominalizations sound pompous."},{"t":260,"text":"Prefer concrete subjects and verbs that do something."}]'::jsonb),
('eng-12-l4', 'eng-12', 4, 'The Art of the Metaphor', 'A0edKgL9EgM', 6, 'Metaphors make handles for ideas. Dickinson, Hughes and Sandburg show how to build one that works.', '[{"id":"metaphor-structure","name":"How metaphors work"},{"id":"imagery","name":"Imagery"},{"id":"figurative-analysis","name":"Analysing figurative language"}]'::jsonb, '["creative-thinking","critical-thinking"]'::jsonb, 'essay-editor', '[{"t":0,"text":"A metaphor says one thing is another so we can see it fresh."},{"t":70,"text":"Dickinson: “Hope is the thing with feathers” — abstract feeling gets a body."},{"t":140,"text":"Langston Hughes: a dream deferred dries up like a raisin in the sun."},{"t":210,"text":"Carl Sandburg: fog comes on little cat feet."},{"t":280,"text":"A good metaphor is precise, surprising, and makes a handle you can hold."}]'::jsonb),
('eng-12-l5', 'eng-12', 5, 'What Makes a Hero?', 'Hhk4N9A0oCA', 5, 'The Hero’s Journey as a structure for stories — and for analysing novels in the exam.', '[{"id":"hero-journey","name":"Stages of the Hero’s Journey"},{"id":"narrative-structure","name":"Narrative structure"},{"id":"character-arc","name":"Character arc"}]'::jsonb, '["critical-thinking"]'::jsonb, 'story-mapper', '[{"t":0,"text":"Harry Potter, Frodo, Katniss — what trials unite them?"},{"t":60,"text":"Joseph Campbell found the same pattern in myths worldwide: the Hero’s Journey."},{"t":120,"text":"Ordinary world, call to adventure, refusal, mentor, crossing the threshold."},{"t":180,"text":"Trials, approach, crisis, treasure, the road back, the return with change."},{"t":250,"text":"Use the cycle to analyse a text — or to notice your own journey."}]'::jsonb),
('eng-12-l6', 'eng-12', 6, 'Building a Fictional World', 'ZQTQSbjecLg', 5, 'Rules, history and daily life make an invented world feel real — and make a short story hold together.', '[{"id":"world-rules","name":"Consistent rules"},{"id":"setting-detail","name":"Setting detail"},{"id":"creative-draft","name":"Drafting a scene"}]'::jsonb, '["creative-thinking"]'::jsonb, 'essay-editor', '[{"t":0,"text":"Tolkien and Rowling built worlds with consistent rules for people, societies, even physics."},{"t":60,"text":"Start with a timeline and the big history of the world."},{"t":120,"text":"Then the rules: government, beliefs, technology, magic or science."},{"t":180,"text":"Then daily life — what people eat, fear, celebrate."},{"t":240,"text":"Every detail you decide makes the next scene easier to write."}]'::jsonb),
('eng-12-l7', 'eng-12', 7, 'What Makes a Poem a Poem?', 'JwhouCNq-Fc', 5, 'Three recognisable traits of poetry, from Muhammad Ali’s two-word poem to prose poems.', '[{"id":"poetic-traits","name":"Traits of poetry"},{"id":"sound-devices","name":"Sound & rhythm"},{"id":"poem-analysis","name":"Unseen poem analysis"}]'::jsonb, '["critical-thinking","creative-thinking"]'::jsonb, 'poem-lab', '[{"t":0,"text":"“Me. We.” — if two words can be a poem, what makes a poem a poem?"},{"t":60,"text":"Poets reach for metaphors: a little machine, a firework, an echo, a dream."},{"t":120,"text":"Trait one: poems emphasise the musical qualities of language."},{"t":170,"text":"Trait two: condensed language — every word carries weight."},{"t":220,"text":"Trait three: intense feeling, often through imagery."},{"t":270,"text":"Shape poems and prose poems bend the rules but keep the traits."}]'::jsonb),
('phy-12-l1', 'phy-12', 1, 'Motion in a Straight Line', 'ZM8ECpBuQYE', 11, 'Position, velocity and acceleration — and how to read them off graphs of a real car.', '[{"id":"position-velocity","name":"Position & velocity"},{"id":"acceleration","name":"Acceleration"},{"id":"kinematic-graphs","name":"Reading motion graphs"}]'::jsonb, '["problem-solving"]'::jsonb, 'motion-graphs', '[{"t":0,"text":"Four quantities describe one-dimensional motion: time, position, velocity, acceleration."},{"t":90,"text":"Velocity is the rate of change of position; acceleration the rate of change of velocity."},{"t":200,"text":"A position graph’s slope is velocity. A velocity graph’s slope is acceleration."},{"t":330,"text":"Constant acceleration gives the kinematic equations."},{"t":460,"text":"Average velocity = displacement ÷ time; not the same as average speed."},{"t":580,"text":"Application: was the car speeding? Use the graph to decide."}]'::jsonb),
('phy-12-l2', 'phy-12', 2, 'Derivatives in Physics', 'ObHJJYvu3RE', 10, 'Calculus is the language of motion: velocity is the derivative of position, acceleration of velocity.', '[{"id":"derivative-motion","name":"Derivatives of motion"},{"id":"power-rule-physics","name":"Power rule in physics"},{"id":"free-fall","name":"Free fall & g"}]'::jsonb, '["problem-solving","critical-thinking"]'::jsonb, 'free-fall', '[{"t":0,"text":"Position x(t) = t². Velocity is the derivative: 2t."},{"t":110,"text":"The power rule: bring the exponent down, subtract one."},{"t":220,"text":"Acceleration is the second derivative — for t² it is a constant 2."},{"t":330,"text":"Free fall: a = −9.8 m/s² near Earth, in a vacuum everything falls the same way."},{"t":450,"text":"Air resistance changes the story: terminal velocity."},{"t":540,"text":"Integrating acceleration gives velocity; integrating velocity gives position."}]'::jsonb),
('phy-12-l3', 'phy-12', 3, 'Newton’s Laws', 'kKKM8Y-u7ds', 11, 'Inertia, F = ma, and action–reaction — with free-body diagrams you can build yourself.', '[{"id":"inertia","name":"First law: inertia"},{"id":"f-equals-ma","name":"Second law: F = ma"},{"id":"action-reaction","name":"Third law pairs"},{"id":"free-body","name":"Free-body diagrams"}]'::jsonb, '["problem-solving","critical-thinking"]'::jsonb, 'force-cart', '[{"t":0,"text":"Newton published three laws in the Principia in 1687."},{"t":90,"text":"First law: an object stays at rest or in uniform motion unless a net force acts."},{"t":200,"text":"Second law: net force equals mass times acceleration."},{"t":320,"text":"Third law: every force has an equal and opposite partner on the other object."},{"t":430,"text":"The normal force, equilibrium, and the elevator problem."},{"t":560,"text":"Free-body diagrams: draw every force on one object, then sum."}]'::jsonb),
('phy-12-l4', 'phy-12', 4, 'Uniform Circular Motion', 'bpFK2VCRHUs', 10, 'Why you lean in a turning car: centripetal acceleration and the “fictitious” centrifugal force.', '[{"id":"centripetal","name":"Centripetal acceleration"},{"id":"period-frequency","name":"Period & frequency"},{"id":"fictitious-force","name":"Fictitious forces"}]'::jsonb, '["critical-thinking"]'::jsonb, 'circular-motion', '[{"t":0,"text":"Is centrifugal force real? It is a thing — but a fictitious one."},{"t":100,"text":"An object moving in a circle at constant speed is still accelerating: direction changes."},{"t":220,"text":"Centripetal acceleration = v²/r, pointing to the centre."},{"t":340,"text":"Period T and frequency f: v = 2πr/T."},{"t":450,"text":"In the car, your inertia carries you straight; the door pushes you into the turn."}]'::jsonb),
('phy-12-l5', 'phy-12', 5, 'Newtonian Gravity', '7gf6YpdvtE0', 9, 'The apple and the Moon obey the same law. Orbits, g on other planets, and why astronauts float.', '[{"id":"universal-gravitation","name":"Universal gravitation"},{"id":"orbits","name":"Orbits"},{"id":"g-variation","name":"g on other worlds"}]'::jsonb, '["problem-solving","creative-thinking"]'::jsonb, 'orbit-sim', '[{"t":0,"text":"The apple story is mostly legend — but the insight is real."},{"t":90,"text":"F = G·m₁·m₂ / r². Double the distance, a quarter of the force."},{"t":200,"text":"The Moon is falling toward Earth constantly — it just keeps missing."},{"t":310,"text":"Surface gravity g = G·M / R². On the Moon g is about 1.6 m/s²."},{"t":420,"text":"Astronauts float because they and the station fall together."}]'::jsonb),
('phy-12-l6', 'phy-12', 6, 'Work, Energy & Power', 'w4QFJb9a8vo', 10, 'Energy is the currency of physics: a roller coaster trades height for speed and friction takes a cut.', '[{"id":"work","name":"Work = F·d"},{"id":"energy-conservation","name":"Conservation of energy"},{"id":"power","name":"Power"}]'::jsonb, '["problem-solving"]'::jsonb, 'roller-coaster', '[{"t":0,"text":"Work has a precise meaning: force times displacement along the force."},{"t":110,"text":"Kinetic energy ½mv²; gravitational potential energy mgh."},{"t":230,"text":"Conservation: total energy stays constant unless work is done by friction or a motor."},{"t":350,"text":"Spring potential energy ½kx²."},{"t":460,"text":"Power is work per time — watts."}]'::jsonb),
('phy-12-l7', 'phy-12', 7, 'Collisions & Momentum', 'Y-QOfc2XqOk', 9, 'Momentum, impulse and why crumple zones save lives — elastic vs inelastic collisions you can run.', '[{"id":"momentum","name":"Momentum = mv"},{"id":"impulse","name":"Impulse"},{"id":"collision-types","name":"Elastic vs inelastic"}]'::jsonb, '["problem-solving","critical-thinking"]'::jsonb, 'collision-lab', '[{"t":0,"text":"Momentum = mass × velocity. It is conserved in every collision."},{"t":100,"text":"Impulse = force × time = change in momentum."},{"t":210,"text":"Crumple zones lengthen the collision time, lowering the force on you."},{"t":320,"text":"Elastic collisions conserve kinetic energy; inelastic ones do not."},{"t":430,"text":"Centre of mass: the point that moves as if all mass were there."}]'::jsonb)
insert into public.badges ("id", "name", "category", "skill", "icon", "rarity", "description", "how_to_earn") values
('first-bolt', 'First Bolt', 'Milestone', 'consistency', 'zap', 'common', 'Completed your first lesson journey checkpoint.', 'Finish any lesson, including its interactive question.'),
('always-here', 'Always Here', 'Consistency', 'consistency', 'calendar-check', 'uncommon', 'A full month with a straight attendance record — no absences, no lates.', 'Keep a clean attendance record for a whole calendar month.'),
('monthly-podium', 'Monthly Podium', 'Challenge', 'problem-solving', 'trophy', 'rare', 'Finished in the top 3 of a course leaderboard at the end of a month.', 'Earn points by completing lessons, practice branches and lab challenges. Top 3 per course each month get stamped.'),
('oral-defender', 'Oral Defender', 'Verified Demonstration', 'communication', 'mic', 'rare', 'Defended a solution out loud to the teacher and answered follow-up questions.', 'Request an oral defense on any completed lesson; the teacher validates it.'),
('project-proof', 'Project Proof', 'Verified Demonstration', 'creative-thinking', 'hammer', 'rare', 'Built a real project tagged to the skills it proves, validated by a teacher.', 'Submit a project in Project Showcase with skill tags. Earned when a teacher validates it.'),
('critical-eye', 'Critical Eye', 'Thinking Lab', 'critical-thinking', 'search', 'uncommon', 'Caught planted errors in confident AI answers five times.', 'Win 5 rounds of Spot the Flaw.'),
('explainer', 'Explainer', 'Thinking Lab', 'communication', 'message-circle', 'uncommon', 'Reached “deep understanding” in Explain Back three times.', 'Answer the why / what-if / new-scenario follow-ups with evidence in Explain Back.'),
('bot-teacher', 'Bot Teacher', 'Thinking Lab', 'ai-literacy', 'bot', 'uncommon', 'Spotted and corrected the confused AI classmate’s mistakes.', 'Complete 3 Teach the Bot sessions with every mistake corrected.'),
('evidence-detective', 'Evidence Detective', 'Thinking Lab', 'critical-thinking', 'fingerprint', 'uncommon', 'Judged sources, claims and data for credibility with a 90%+ accuracy.', 'Score 90% or above in an Evidence Detective case file.'),
('decision-maker', 'Decision Maker', 'Thinking Lab', 'problem-solving', 'git-branch', 'uncommon', 'Reasoned well under uncertainty in the Decision Simulator.', 'Finish a Decision Simulator scenario with a justified decision scored 80+.'),
('debate-victor', 'Debate Victor', 'Thinking Lab', 'critical-thinking', 'swords', 'rare', 'Out-argued the adaptive AI opponent in Debate Arena.', 'Win a 4-round debate in Debate Arena with a reasoning score above the AI.'),
('curious-mind', 'Curious Mind', 'Learning', 'critical-thinking', 'lightbulb', 'common', 'Asked ten thoughtful questions to the lesson tutor.', 'Ask the AI tutor questions while watching lessons — quality questions count.'),
('comeback', 'Comeback', 'Growth', 'consistency', 'trending-up', 'rare', 'Turned a struggling topic (below 50%) into mastery (above 80%).', 'Complete the extra-practice branch for a weak topic and pass its re-check.'),
('peer-mentor', 'Peer Mentor', 'Verified Demonstration', 'collaboration', 'users', 'rare', 'Helped a classmate master a topic, confirmed by the teacher.', 'Tutor a classmate in a study session the teacher verifies.'),
('momentum', 'Momentum', 'Consistency', 'consistency', 'flame', 'common', 'Seven days of learning in a row.', 'Complete any activity on seven consecutive days.'),
('calculus-navigator', 'Calculus Navigator', 'Mastery', 'problem-solving', 'sigma', 'epic', 'Completed the full Calculus journey.', 'Finish all 7 checkpoints in Calculus: Change & Motion.'),
('force-of-nature', 'Force of Nature', 'Mastery', 'problem-solving', 'atom', 'epic', 'Completed the full Physics journey.', 'Finish all 7 checkpoints in Physics: Mechanics of the Real World.'),
('wordsmith', 'Wordsmith', 'Mastery', 'communication', 'feather', 'epic', 'Completed the full English journey.', 'Finish all 7 checkpoints in English: Argument & Craft.'),
